4 \cdot 3^{2b} + 2 \cdot 3^n &= 2^{n + 2}3^b - 2\cdot 3^b
2 \cdot 3^{2b} + 3^n &= 2^{n+1}3^b - 3^b
2 \cdot 3^b + 3^{n-b} &= 2^{n+1} - 1
3^{n-b} + 1 &= 2^{n+1} - 2 \cdot 3^b
\end{align*}
