draw((0,3)--(0,5)--(1,5)--(1,3)--(0,3));
draw((2,2)--(3,2)--(3,4)--(2,4)--(2,2));
draw((1,4)--(3,4)--(3,5)--(1,5)--(1,4));
draw((3,3)--(4,3)--(4,5)--(3,5)--(3,3));
draw((0,0)--(2,1),red);
draw((2,0)--(0,1),blue);
draw((1,1)--(3,2),red);
draw((3,1)--(1,2),blue);
draw((2,0)--(4,1),red);
draw((4,0)--(2,1),blue);
draw((0,1)--(1,3),red);
draw((1,1)--(0,3),blue);
draw((0,3)--(1,5),red);
draw((0,5)--(1,3),blue);
draw((1,2)--(2,4),red);
